{
  "IP": "neorv32_debug_auth",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Debug authentication state",
      "Unit": "neorv32_debug_auth",
      "Information": "The unit's latched debug-authentication state is set from the incoming authentication value and exposed as valid_o; debug access depends on whether this state is asserted.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The authentication state can be overwritten from wdata_i(0) or cleared by enable_i=0 in the clocked process (lines 54-57), so an unauthorized control can alter it. The state directly drives valid_o (line 66), and reset or disable clears it (lines 51-55), which can withhold debug authorization.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can assert we_i with a chosen wdata_i(0), or drive enable_i low, to forge or clear authentication and thereby enable or deny debug access.",
      "Enters Through": [
        "wdata_i"
      ],
      "Leaves Through": [
        "valid_o"
      ],
      "Entry Lines": [
        57
      ],
      "Held Lines": [
        52,
        55,
        57
      ],
      "Exit Lines": [
        66
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Debug authentication enable control",
      "Unit": "neorv32_debug_auth",
      "Information": "The external enable control determines whether the authentication state is forcibly cleared or may retain and change; debug availability depends on this control.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "enable_i is a security-relevant control because the RTL uses it to clear authenticated_q when low (line 54), so changing the control changes the authentication state. Driving enable_i low clears the state and causes valid_o to be deasserted through the assignment at line 66, blocking debug authorization.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can force enable_i low while authentication is active, clearing the state and preventing the debug function from being available.",
      "Enters Through": [
        "enable_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        54
      ],
      "Held Lines": [],
      "Exit Lines": []
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Debug authentication write command",
      "Unit": "neorv32_debug_auth",
      "Information": "The write command determines whether the incoming authentication value is applied to the debug-authentication state, allowing that state to be established or overwritten.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "we_i selects the assignment that copies wdata_i(0) into authenticated_q (lines 56-57), so unauthorized assertion can modify the security state. Suppressing the write command can prevent authentication from being established, while asserting it with a clearing value can deny debug availability (lines 56-57 and 66).",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can suppress or assert we_i with a selected wdata_i(0) value to prevent authentication or overwrite the current authentication state.",
      "Enters Through": [
        "we_i"
      ],
      "Leaves Through": [],
      "Entry Lines": [
        56
      ],
      "Held Lines": [],
      "Exit Lines": []
    }
  ],
